function debounce(fn, delay) {
  let timer = null;
  return function (...args) {
    const ctx = this;
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(ctx, args), delay);
  };
}

function isValid(s) {
  const st = [];
  const pair = { ')': '(', ']': '[', '}': '{' };
  for (const ch of s) {
    if (ch in pair) {
      if (st.pop() !== pair[ch]) return false;
    } else {
      st.push(ch);
    }
  }
  return st.length === 0;
}

async function sleep(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}
